import AppKit

extension AgentServer {

    // MARK: - Export

    /// `export` — ⌘E (`EditorViewController.exportProjectCommand` and
    /// `ExportSheetController`). The preset names the ENCODING — a container
    /// and a codec, nothing about size — and the size is the sheet's separate
    /// choice, in the Size popup's own vocabulary and defaulting as the popup
    /// does to its first row: the document's size, or an image format's cap.
    /// The CORE resolves both into concrete settings (`rc_export_settings`)
    /// that go to the same `Exporter.export` the sheet uses: there is exactly
    /// one writer, so an agent export and a menu export cannot disagree.
    ///
    /// Answers AT ONCE (spec §11 #326): every refusal is made here, before
    /// anything is queued — the arguments, the core's settings, the folder,
    /// the graphics gate, and the frame limit and same-shape rule
    /// (`Exporter.settingsRefusal`, #470) — and the export is then a job in the Export
    /// Queue, exactly as the sheet's Add to Queue makes one, answered as
    /// `{export_id, path, status}`. `export_status` follows the job and
    /// `cancel_export` stops it (`AgentServer+ExportStatus.swift`); a failure
    /// while writing comes back from there. The queue window is not shown.
    ///
    /// One argument is NOT a setting and never reaches the core:
    /// `burn_in_timecode` is a recipe option (`RecipeOptions`), read below
    /// beside the overrides it deliberately does not join.
    ///
    /// The finished job's answer carries the sound the file actually holds —
    /// its integrated loudness and true peak, measured on the way through —
    /// for every format that has any, whether `loudness_lufs` was asked for
    /// or not, and, with `stems` (the sheet's Stems popup, spec §11 AU-108),
    /// each stem file beside the mix.
    func exportProject(_ a: [String: Any]) throws -> String {
        // The clock `export_status`'s `elapsed` runs on, read before any check.
        let started = ProcessInfo.processInfo.systemUptime
        let presetID = try requiredString(a, "preset")
        let path = try requiredString(a, "path")
        let wholeProject = (try stringArg(a, "range") ?? "project").lowercased()
        guard ["project", "in_out"].contains(wholeProject) else {
            throw ToolError(
                message: "range must be \"project\" (the whole timeline) or \"in_out\" "
                    + "(the in/out range set_range set), not \"\(wholeProject)\".")
        }
        // The export sheet's burn-in checkbox — and read HERE rather than
        // into `overrides` below, which is the whole of the decision. A
        // recipe option changes the PICTURE, so it travels with the
        // description of the picture: `export_overrides.rs` ignores a key it
        // does not know, on purpose, so a `burn_in_timecode` posted through
        // `rc_export_settings` would vanish without a word and this tool
        // would report success on an un-burnt file. It goes to `Exporter`
        // beside the settings instead (`RecipeOptions`, `Exporter.export`),
        // which is also what reaches GIF and APNG — those never go through
        // `ExportWriter` at all.
        let options = RecipeOptions(burnInTimecode: try boolArg(a, "burn_in_timecode") ?? false)
        let prepared = try onMain {
            () throws -> (ProjectDocument, ReelProject, [UInt32: URL], ExportSettings, GraphicSet?)
            in
            let document = try self.target(a)
            guard document.project.duration > 0 else {
                throw ToolError(message: "There is nothing on the timeline to export.")
            }
            let settings = try self.exportSettings(
                a, on: document, preset: presetID, range: wholeProject)
            return (
                document, document.project, document.mediaURLs(), settings,
                GraphicRegistry.shared.snapshot(for: document.recipeKey)
            )
        }
        let (document, project, urls, settings, graphics) = prepared
        let url = try Self.requireFolder(
            of: Self.destinationURL(path, extension: Exporter.fileExtension(for: settings)))

        // The graphics gate, here rather than only in the writer: a module
        // that does not compile refuses the CALL, so nothing is queued that
        // could only fail (`Exporter.graphicsRefusal`, the writer's own gate).
        if let refusal = Exporter.graphicsRefusal(
            project: project, settings: settings, graphics: graphics)
        {
            throw ToolError(message: refusal.localizedDescription)
        }
        // The same, for the two rules the sheet shows in its readout (#470).
        if let refusal = Exporter.settingsRefusal(settings, project: project) {
            throw ToolError(message: refusal.localizedDescription)
        }
        let (id, status) = onMain { () -> (UInt64, String) in
            // The editor pauses before its own export so the player is not
            // decoding the same media; the agent's does the same.
            self.editor(document)?.playback.pause()
            let id = ExportQueueController.shared.enqueue(
                project: project, urls: urls, settings: settings, to: url, options: options,
                graphics: graphics)
            AgentExports.shared.track(
                id, settings: settings, burnInTimecode: options.burnInTimecode, started: started)
            let word = ExportQueueController.shared.job(id).map {
                Self.exportStatusWord($0.state)
            }
            return (id, word ?? "queued")
        }
        return try jsonResult(["export_id": id, "path": url.path, "status": status])
    }

    /// The core's settings for `export`'s arguments, every override read as
    /// the sheet's popups spell it, and every refusal the tool's own. Main
    /// only. `range` is the call's `range`, already lower-cased.
    func exportSettings(
        _ a: [String: Any], on document: ProjectDocument, preset: String, range: String
    ) throws -> ExportSettings {
        // The Range popup of the export sheet, in the sheet's own terms:
        // "Whole project" is no override at all, "In/out range" is the
        // core's ONE nested `range` object (`export.rs`). The core snaps
        // it to the frame grid and clamps it to the project.
        var overrides: [String: Any] = [:]
        if range == "in_out" {
            guard let inOut = document.inOutRange, inOut.end > inOut.start else {
                throw ToolError(
                    message: "This project has no in/out range — set one with set_range "
                        + "{start, end}, or export with range \"project\".")
            }
            overrides["range"] = ["start": inOut.start, "duration": inOut.end - inOut.start]
        }
        // The sheet's Quality popup, in the core's own words: it resolves
        // a tier into these two keys and nothing else
        // (`ExportSheetController.overrides()`), so the agent spells them
        // the same way rather than re-deriving a rate from a tier name.
        // The core validates them — positive, u32 — and an unset key means
        // "the preset decides", which is what a nil bitrate already means
        // to the writer.
        if let video = try intArg(a, "video_bitrate") {
            overrides["video_bitrate"] = video
        }
        if let audio = try intArg(a, "audio_bitrate") {
            overrides["audio_bitrate"] = audio
        }
        // The sheet's Loudness popup, in the core's words again — and
        // through `doubleArg`, not `intArg`: −14.5 LUFS is a real request
        // and every one of these figures is a negative fraction. Neither
        // is validated here. `export_overrides.rs` owns the bounds
        // (−70…0 and −20…0) and names the offending value the way the
        // bitrate refusals do; either may come alone, the ceiling being
        // the master limiter's (spec §11 AU-27).
        // Restating a bound here would be a second spelling of it to
        // drift from the first.
        // The sheet sends both together and fixes the ceiling at
        // −1 dBTP; a caller that wants −0.3 or −2.0 says so here.
        if let target = try doubleArg(a, "loudness_lufs") {
            overrides["loudness_lufs"] = target
        }
        if let ceiling = try doubleArg(a, "peak_dbtp") {
            overrides["peak_dbtp"] = ceiling
        }
        // The sheet's Size popup: a row id, or "Custom…" as an explicit
        // [width, height]. Absent is no override at all, so the tool's
        // default and the sheet's are one code path in the core — the
        // document's size, or an image format's cap.
        if let size = try exportSizeArg(a, document.project, preset: preset) {
            overrides["width"] = size.width
            overrides["height"] = size.height
        }
        // The sheet's Dynamic Range popup (spec §11 HD-14 (c)), forwarded
        // unread: the core's reader and resolver own its three words, its
        // per-row defaults and both refusals, each in its own sentence.
        if let dynamicRange = a["dynamic_range"] {
            overrides["dynamic_range"] = dynamicRange
        }
        // The sheet's Speed popup (spec §11 CX-12 (2)), forwarded unread on the
        // same terms: the core reads the three words and refuses a row without one.
        if let speed = a["encoder_speed"] {
            overrides["encoder_speed"] = speed
        }
        // The sheet's Bit depth popup (spec §11 AU-29), forwarded unread on the
        // same terms: the core reads 16 or 24 and refuses a row without a depth.
        if let bits = a["audio_bits"] {
            overrides["audio_bits"] = bits
        }
        // The sheet's Stems popup (spec §11 AU-108), forwarded unread on the same
        // terms: the core reads "tracks" or "names", refuses a movie row, and refuses
        // a project with no track heard.
        if let stems = a["stems"] {
            overrides["stems"] = stems
        }
        do {
            return try ReelExport.settings(document.project, preset: preset, overrides: overrides)
        } catch {
            throw Self.coreRefusal(error)
        }
    }

    /// The file `export` writes for these arguments: the settings' own
    /// extension on `path`, so the assistant's question names what the tool
    /// will write (spec §11 AI-21 (c)). It throws what the tool would refuse.
    /// Main only, on the document the lane pinned.
    func exportDestination(_ a: [String: Any], on document: ProjectDocument) throws -> URL {
        let preset = try requiredString(a, "preset")
        let path = try requiredString(a, "path")
        let range = (try stringArg(a, "range") ?? "project").lowercased()
        let settings = try exportSettings(a, on: document, preset: preset, range: range)
        return Self.destinationURL(path, extension: Exporter.fileExtension(for: settings))
    }

    /// The `size` argument of `export`, in the Size popup's vocabulary: a row
    /// id resolved through the same `rc_export_sizes` the popup is built from
    /// (`document`, `preset`, `2160p`, `1440p`, `1080p`, `720p` — `ExportSize`
    /// in `ReelCore.swift` says what each means, and `core/src/export_size.rs`
    /// why every document lists every row), or the popup's "Custom…" as an
    /// explicit `[width, height]`. nil when absent, which is no override: the
    /// core's default for the preset.
    ///
    /// A value that is neither is refused by NAME, never read as absent — the
    /// rule every reader in `AgentServer+Arguments.swift` keeps, and the root
    /// `CLAUDE.md`'s: a value a handler cannot read is refused by name, never
    /// dropped. A `size` dropped in silence would export at the wrong size
    /// and report success. A custom
    /// size outside the sheet's own field range is refused the same way,
    /// where the sheet clamps: a tool has no field to clamp in view of the
    /// caller, and the sheet's reason — a mistyped digit must not reach the
    /// encoder as a 300 000-pixel frame — holds for a model's typo too.
    private func exportSizeArg(
        _ a: [String: Any], _ project: ReelProject, preset: String
    ) throws -> (width: Int, height: Int)? {
        guard let raw = a["size"], !(raw is NSNull) else { return nil }
        // The rows come first, whichever spelling follows: every refusal
        // below lists the ids from them rather than from a vocabulary
        // restated here, which could drift from the core's, and a preset the
        // core does not know is refused at this point in the same words
        // `exportProject` would use a call later.
        let rows: [ExportSize]
        do {
            rows = try ReelExport.sizes(project, preset: preset)
        } catch {
            throw Self.coreRefusal(error)
        }
        let ids = rows.map { $0.id }.joined(separator: ", ")
        if let id = raw as? String {
            guard let row = rows.first(where: { $0.id == id }) else {
                throw ToolError(
                    message: "No export size is called \"\(id)\" for \(preset). The sizes "
                        + "are: \(ids) — or pass [width, height].")
            }
            return (row.width, row.height)
        }
        if let array = raw as? [Any], array.count == 2 {
            let edges = array.compactMap(Self.wholeEdge)
            if edges.count == 2 {
                let range = ExportSheetController.sizeRange
                // Each refusal of a `size` offers the OTHER spelling: the
                // unknown-id one above names the custom form, and this one
                // names the rows, so a caller who meant a standard size and
                // reached for numbers has the ids in front of it.
                guard edges.allSatisfy(range.contains) else {
                    throw ToolError(
                        message: "A custom size must be \(range.lowerBound)…\(range.upperBound) "
                            + "px on each edge, not [\(edges[0]), \(edges[1])] — or pass a "
                            + "row: \(ids).")
                }
                return (edges[0], edges[1])
            }
        }
        throw ToolError(
            message: "size must be a row of the export sheet's Size popup — \(ids) — or "
                + "[width, height] in px, not \(Self.spelled(raw)).")
    }

    /// One edge of a custom size as a whole number, or nil for a value that
    /// is not one — which sends the whole `size` to the refusal that names
    /// it. The coercion `intArg` applies holds: a string spelling of a whole
    /// number is a JSON-typing slip, not a different request. A fraction is
    /// refused rather than truncated, since 1920.5 is not a width the caller
    /// can have meant. So is a boolean: JSON's `true` arrives as an
    /// `NSNumber` like any other and would read as 1 through it, and the
    /// Core Foundation type is the one thing that still tells `true` from
    /// `1`.
    private static func wholeEdge(_ value: Any) -> Int? {
        if let number = value as? NSNumber {
            guard CFGetTypeID(number) != CFBooleanGetTypeID() else { return nil }
            let real = number.doubleValue
            return real.isFinite && real == real.rounded() ? number.intValue : nil
        }
        return (value as? String).flatMap(Int.init)
    }

    /// A refusal from `rc_export_settings` or `rc_export_sizes` as the tool's
    /// error. The core's message passes through as it was, with one
    /// addition: an unknown preset id — the message that begins
    /// "unknown export preset", the same words from either call
    /// (`export.rs`) — gets the ids the table does take appended, because
    /// without them it is the one error a model cannot correct itself from,
    /// since nothing else lists the table. A refused bitrate or range keeps
    /// its own message alone: a list of presets under it would be a false
    /// lead.
    private static func coreRefusal(_ error: any Error) -> ToolError {
        let message = error.localizedDescription
        guard message.hasPrefix("unknown export preset") else {
            return ToolError(message: message)
        }
        let names = ReelExport.presets().map { $0.id }.joined(separator: ", ")
        return ToolError(message: "\(message). The presets are: \(names).")
    }

    /// A caller's value as it was spelled, for a refusal that names it: its
    /// JSON where it is JSON, its Swift description otherwise.
    private static func spelled(_ raw: Any) -> String {
        guard JSONSerialization.isValidJSONObject([raw]),
            let data = try? JSONSerialization.data(
                withJSONObject: raw, options: [.fragmentsAllowed]),
            let text = String(data: data, encoding: .utf8)
        else { return String(describing: raw) }
        return text
    }
}

import Foundation

// MARK: - export_status and cancel_export

/// The agent's half of the Export Queue (spec §11 #326): `export` enqueues a
/// job in `ExportQueueController.shared` and answers its id at once, and the
/// two tools here follow it. `export_status` mirrors Window ▸ Export Queue's
/// row for that job (`ExportQueueWindowController`) — its state, its progress
/// bar, its phase and its closing sentence — and `cancel_export` mirrors the
/// row's Cancel button, which calls the same `ExportQueueController.cancel`.
///
/// **Only ids `export` returned are reachable.** A person's own queued job has
/// no record here and is answered as unknown: the mirror follows what the
/// agent started, not the queue as a whole.
///
/// **A record outlives its row.** The queue drops a finished job on Remove or
/// Clear Finished, and an agent that asks after that must still hear how it
/// ended, so `AgentExports` copies each tracked job's state on every queue
/// change — synchronously, on main, inside the queue's own post — and stamps
/// the finish (its time and the file's size) on its first terminal sight.
/// Records last for the launch and hold no project handle or graphic set.
extension AgentServer {

    /// `export_status {export_id}` — the row of Window ▸ Export Queue for a job
    /// `export` started, read now; it never waits.
    func exportStatus(_ a: [String: Any]) throws -> String {
        let id = try exportIDArg(a)
        guard let status = AgentExports.shared.status(id) else {
            throw Self.unknownExport(id)
        }
        return try jsonResult(status)
    }

    /// `cancel_export {export_id}` — the Export Queue row's Cancel. A queued
    /// or running job is cancelled through the queue (a running one answers
    /// through the writer, so it may still read `running` here); a finished
    /// one is left alone and answered as it is.
    func cancelExport(_ a: [String: Any]) throws -> String {
        let id = try exportIDArg(a)
        guard AgentExports.shared.status(id) != nil else {
            throw Self.unknownExport(id)
        }
        if let job = ExportQueueController.shared.job(id), !job.state.isFinished {
            ExportQueueController.shared.cancel(id)
        }
        guard let status = AgentExports.shared.status(id) else {
            throw Self.unknownExport(id)
        }
        return try jsonResult(status)
    }

    /// The word a status answer spells a queue state with.
    static func exportStatusWord(_ state: ExportQueueController.State) -> String {
        switch state {
        case .waiting: return "queued"
        case .running: return "running"
        case .completed: return "done"
        case .failed: return "failed"
        case .cancelled: return "cancelled"
        }
    }

    /// `export_id`, required and whole. An id below 1 is no id `export`
    /// returned, so it is refused as an unknown one rather than converted.
    private func exportIDArg(_ a: [String: Any]) throws -> UInt64 {
        guard let raw = try intArg(a, "export_id") else {
            throw ToolError(message: "Missing required argument: export_id")
        }
        guard raw >= 1 else {
            throw ToolError(
                message: "No export this launch has export_id \(raw) — ids come from export "
                    + "and last until Frame Job quits.")
        }
        return UInt64(raw)
    }

    private static func unknownExport(_ id: UInt64) -> ToolError {
        ToolError(
            message: "No export this launch has export_id \(id) — ids come from export and "
                + "last until Frame Job quits.")
    }
}

/// What `AgentExports` keeps of one tracked job: the queue row's fields as
/// last seen, plus what the `done` answer needs that the job does not carry.
private struct AgentExportRecord {
    let settings: ExportSettings
    let burnInTimecode: Bool
    /// `systemUptime` at the `export` handler's first line.
    let started: TimeInterval
    var state: ExportQueueController.State
    var progress: Double
    var phase: String?
    var message: String?
    var destination: URL
    var loudness: ExportLoudness?
    var graphicWarnings: [ExportGraphicWarning]
    /// The media whose cursor file was not drawn (spec §11 CU-37 (c)).
    var cursorWarnings: [ExportCursorWarning]
    /// `systemUptime` at the first terminal sight, nil until then.
    var finished: TimeInterval?
    /// The file's size as read at that finish.
    var bytes: Int = 0

    mutating func copy(_ job: ExportQueueController.Job) {
        state = job.state
        progress = job.progress
        phase = job.phase
        message = job.message
        destination = job.destination
        loudness = job.loudness
        graphicWarnings = job.graphicWarnings
        cursorWarnings = job.cursorWarnings
        guard job.state.isFinished, finished == nil else { return }
        finished = ProcessInfo.processInfo.systemUptime
        bytes =
            (try? FileManager.default.attributesOfItem(atPath: job.destination.path)[.size])
            .flatMap { ($0 as? NSNumber)?.intValue } ?? 0
    }
}

/// The records of every export the agent started this launch, by the queue's
/// job id. Main thread only, like the queue it reads.
final class AgentExports {
    static let shared = AgentExports()

    private var records: [UInt64: AgentExportRecord] = [:]
    private var observer: NSObjectProtocol?

    private init() {
        // `queue: nil` runs the block synchronously inside the queue's own
        // post, so a terminal state is copied before any Remove can drop it.
        observer = NotificationCenter.default.addObserver(
            forName: ExportQueueController.didChangeNotification,
            object: ExportQueueController.shared, queue: nil
        ) { [weak self] _ in self?.refresh() }
    }

    /// Starts following a job `export` just enqueued. Reads it AT ONCE: an
    /// early refusal finishes inside `enqueue`, before this is called, so its
    /// terminal post has already gone by.
    func track(
        _ id: UInt64, settings: ExportSettings, burnInTimecode: Bool, started: TimeInterval
    ) {
        // Never nil: `enqueue` appends the job before it returns, an early
        // refusal only finishes it in place, and the only removals (`remove`,
        // `clearFinished`) are the queue window's button actions, which cannot
        // run inside the one main-thread block that enqueues and calls this.
        guard let job = ExportQueueController.shared.job(id) else { return }
        var record = AgentExportRecord(
            settings: settings, burnInTimecode: burnInTimecode, started: started,
            state: job.state, progress: job.progress, phase: job.phase, message: job.message,
            destination: job.destination, loudness: job.loudness,
            graphicWarnings: job.graphicWarnings, cursorWarnings: job.cursorWarnings)
        record.copy(job)
        records[id] = record
    }

    /// The `export_status` answer for `id`, or nil for an id `export` never
    /// returned this launch.
    func status(_ id: UInt64) -> [String: Any]? {
        guard let record = records[id] else { return nil }
        let end = record.finished ?? ProcessInfo.processInfo.systemUptime
        var answer: [String: Any] = [:]
        switch record.state {
        case .running:
            answer["progress"] = record.progress
            if let phase = record.phase { answer["phase"] = phase }
        case .completed:
            answer = AgentServer.exportResult(
                settings: record.settings, burnInTimecode: record.burnInTimecode,
                path: record.destination.path, bytes: record.bytes, loudness: record.loudness,
                graphicWarnings: record.graphicWarnings, cursorWarnings: record.cursorWarnings)
            // The queue row's own success sentence (spec §11 #395), as the
            // row held it at the finish; `exportResult`'s keys stay the ones
            // `export` answered before #326.
            if let message = record.message { answer["message"] = message }
        case .failed, .cancelled:
            answer["reason"] = record.message ?? ""
        case .waiting:
            // The memory hold's sentence, present only while held (spec §11 CX-18).
            if let held = record.message { answer["waiting"] = held }
        }
        if record.state == .waiting || record.state == .running,
            let seconds = ExportEncoderCosts.estimatedSeconds(for: record.settings)
        {
            answer["estimated_seconds"] = Int(seconds.rounded())
        }
        answer["export_id"] = id
        answer["status"] = AgentServer.exportStatusWord(record.state)
        answer["path"] = record.destination.path
        answer["elapsed"] = ((end - record.started) * 1000).rounded() / 1000
        return answer
    }

    /// Copies every unfinished tracked job from the queue.
    private func refresh() {
        let queue = ExportQueueController.shared
        for (id, record) in records where record.finished == nil {
            guard let job = queue.job(id) else { continue }
            var updated = record
            updated.copy(job)
            records[id] = updated
        }
    }
}

_OWN_PIDS = set()       # every pid a record of this process has owned


def _say(text):
    """One line on stderr; never raises."""
    try:
        sys.stderr.write(text + "\n")
        sys.stderr.flush()
    except Exception:
        pass


def _off(what, error):
    _say(f"mcp: the defaults guard is off for {what}: {type(error).__name__}")


def _holder(socket_path):
    """`socket_pid` for the guard: None for anything it raises, so an `lsof`
    answer that cannot be read costs neither a record nor a found move."""
    try:
        return socket_pid(socket_path)
    except Exception:
        return None


def _sharing(domain):
    """`sharing_pids` for the guard: [] for anything it raises. With no pid
    to blame, a moved key then ends the script instead of only printing."""
    try:
        return proof_defaults.sharing_pids(domain)
    except Exception:
        return []


def _record(socket_path, domain, own=()):
    """Starts guarding `domain` for `socket_path`, replacing any record."""
    try:
        own = {pid for pid in own if pid is not None}
        _OWN_PIDS.update(own)
        before = proof_defaults.snapshot(domain)
        _GUARDED[str(socket_path)] = {
            "domain": domain, "before": before, "then": set(_sharing(domain)), "own": own}
        if before is None:
            _say(_unread(domain, socket_path, "at the record"))
    except Exception as error:  # the guard never raises into a proof, and says when it is off
        _off(socket_path, error)


def _own(socket_path, pid):
    record = _GUARDED.get(str(socket_path))
    if record is not None and pid is not None:
        record["own"].add(pid)
        _OWN_PIDS.add(pid)


_FRESH_CHECKED = set()  # (socket path, pid) whose instance proof_app has checked


def _require_running_fresh(socket_path):
    """`proof_app.require_running_fresh` on the pid holding the socket, once
    per (socket, pid); raises `proof_app.StaleApp`. With no pid, one stderr
    line and no refusal."""
    pid = socket_pid(socket_path)
    if pid is None:
        _say(f"mcp: no pid holds {socket_path}; the instance's freshness is not checked")
    elif (socket_path, pid) not in _FRESH_CHECKED:
        proof_app.require_running_fresh(pid)
        _FRESH_CHECKED.add((socket_path, pid))


def _pid_domain(pid):
    """The bundle identifier of the executable `ps` names for `pid`, else None."""
    try:
        named = subprocess.run(["ps", "-p", str(pid), "-o", "comm="],
                               capture_output=True, text=True, timeout=30)
        executable = named.stdout.strip()
        return proof_defaults.bundle_domain(executable) if executable else None
    except Exception:
        return None


def _rehome(socket_path, pid, domain):
    """Moves a `scratch_socket()` record to the bundle domain of the pid that
    holds the socket, owning it: the instance a script started itself."""
    old = _GUARDED[socket_path]["domain"]
    _say(f"mcp: the defaults guard moved {socket_path} from {old} to {domain}, the bundle of pid "
         f"{pid}; a write before this connect is not seen")
    _record(socket_path, domain, own=[pid])


def _guard_handed(socket_path):
    """Records a socket with no record: the domain of the executable holding
    it, else the app's, that pid owned. When the socket's file is there and
    `lsof` names no pid for it, asked twice, that is said on stderr: the
    record then guards the app's domain and cannot tell the handed instance
    from another Frame Job, so a moved key is only printed unless `lsof` names
    the pid at the compare. A pid whose bundle identifier cannot be read is
    said too: the record then guards the app's domain. A record that owns no
    pid (one `scratch_socket()` made) is re-homed (`_rehome`) when the
    holder's bundle domain can be read and differs from it."""
    try:
        record = _GUARDED.get(socket_path)
        if record is not None:
            if not record["own"]:
                pid = _holder(socket_path)
                domain = _pid_domain(pid) if pid is not None else None
                if domain is not None and domain != record["domain"]:
                    _rehome(socket_path, pid, domain)
            return
        pid = _holder(socket_path)
        if pid is None and os.path.exists(socket_path):
            time.sleep(0.5)
            pid = _holder(socket_path)
        domain = None
        if pid is not None:
            domain = _pid_domain(pid)
            if domain is None:
                _say(f"mcp: the defaults guard could not read the bundle identifier of pid {pid} "
                     f"holding {socket_path}; it guards {proof_defaults.APP_DOMAIN}, which is "
                     "that instance's domain only if it is the real build")
        elif os.path.exists(socket_path):
            _say(f"mcp: the defaults guard found no pid holding {socket_path}; it guards "
                 f"{proof_defaults.APP_DOMAIN} and cannot tell this instance from another "
                 "Frame Job, so a moved key is only printed unless `lsof` names it at the compare")
        _record(socket_path, domain or proof_defaults.APP_DOMAIN, own=[pid])
    except Exception as error:
        _off(socket_path, error)


def defaults_moved(socket_path):
    """Every moved key NAME of that socket's guarded domain since its record
    was made; [] when the socket is not guarded."""
    record = _GUARDED.get(str(socket_path))
    if record is None:
        return []
    try:
        return proof_defaults.moved(record["before"],
                                    proof_defaults.snapshot(record["domain"]))
    except Exception:
        return []


def _moved_line(domain, names, others):
    return (f"mcp: DEFAULTS MOVED in {domain}: {', '.join(names)} (other Frame Job pids: "
            f"{', '.join(str(pid) for pid in others) or 'none'})")


def _unread(domain, socket_path, when):
    return (f"mcp: the defaults guard could not read {domain} {when} (`defaults export` did "
            f"not answer); it cannot see a moved key for {socket_path}")


def _finish(socket_path, record):
    """Compares `record`'s domain now. An owner-visible moved key is appended
    to `DEFAULTS_MOVED` and printed on stderr, and no `Exception` after the
    compare can drop it."""
    try:
        after = proof_defaults.snapshot(record["domain"])
        names = proof_defaults.owner_visible(proof_defaults.moved(record["before"], after))
    except Exception as error:
        _off(socket_path, error)
        return
    if after is None and record["before"] is not None:
        _say(_unread(record["domain"], socket_path, "at the compare"))
    if not names:
        return
    others = set(record["then"]) | set(_sharing(record["domain"]))
    others -= _OWN_PIDS | set(record["own"])
    others.discard(_holder(socket_path))
    entry = (record["domain"], names, sorted(others))
    DEFAULTS_MOVED.append(entry)
    _say(_moved_line(*entry))


def _exit_failed(lines):
    """Flushes stdout, writes `lines` to stderr and ends the process with
    `DEFAULTS_EXIT`, so they are the output's last and the status is 3 (a
    `SystemExit` raised in an `atexit` handler would leave the status 0)."""
    try:
        sys.stdout.flush()
    except Exception:
        pass
    try:
        sys.stderr.write("".join(line + "\n" for line in lines))
        sys.stderr.flush()
    except Exception:
        pass
    os._exit(DEFAULTS_EXIT)


def _defaults_at_exit():
    """Registered at import, so it runs after any handler a script registers
    later: finishes every record still held, then fails the script when a
    moved key has no other Frame Job to be blamed on."""
    for socket_path in list(_GUARDED):
        try:
            _finish(socket_path, _GUARDED.pop(socket_path))
        except Exception as error:
            _off(socket_path, error)
    try:
        lines = [_moved_line(*entry) for entry in DEFAULTS_MOVED if not entry[2]]
    except Exception as error:
        _off("its exit handler", error)
        return
    if lines:
        _exit_failed(lines)


atexit.register(_defaults_at_exit)


def target(argv, index=1, env_fallback=True):
    """`argv[index]`, else `$RC_AGENT_SOCKET`; failing both, a usage exit."""
    if len(argv) > index and argv[index]:
        return argv[index]
    if env_fallback and os.environ.get("RC_AGENT_SOCKET"):
        return os.environ["RC_AGENT_SOCKET"]
    script = os.path.basename(argv[0]) if argv else "the proof"
    raise SystemExit(
        f"usage: pass the running instance's socket path (python3 {script} <dir>/agent.sock), "
        "the RC_AGENT_SOCKET it was launched with" + ("" if not env_fallback else
                                                     ", or set RC_AGENT_SOCKET"))


# ---- the launcher ----------------------------------------------------------------

class Launched:
    """One instance `launch` started: its child, socket, log and client."""

    def __init__(self, child, socket_path, log_path, client):
        self.child = child
        self.socket_path = socket_path
        self.log_path = log_path
        self.client = client

    def stop(self, grace=30):
        """Terminates this child alone, then kills it after `grace`."""
        if self.child is None or self.child.poll() is not None:
            return
        self.child.terminate()
        try:
            self.child.wait(timeout=grace)
        except subprocess.TimeoutExpired:
            self.child.kill()
            self.child.wait()


def _child_env():
    sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                    "graphics_spike"))
    import bounded  # noqa: E402

    return bounded.child_env()


def launch(binary, arguments=(), env=None, socket_path=None, log_path=None, seconds=60,
           timeout=600):
    """Starts `binary -ApplePersistenceIgnoreState YES *arguments` on a
    scratch socket (or `socket_path`), in its own session, logging to
    `log_path` (else beside the socket), and waits up to `seconds` for its
    listening line. `client` is an `MCP` with `timeout`, or None when the
    instance did not come up. A built product older than its inputs is
    refused first (`proof_app.StaleApp`), and so is a bare negative number
    among `arguments` (`proof_app.launch_arguments`, a `ValueError`, #404);
    nothing is started."""
    arguments = proof_app.launch_arguments(arguments)
    proof_app.require_fresh(binary)
    socket_path = str(socket_path or scratch_socket())
    log_path = str(log_path or log_beside(socket_path))
    environment = dict(env) if env is not None else _child_env()
    environment["RC_AGENT_SOCKET"] = socket_path
    offset = os.path.getsize(log_path) if os.path.exists(log_path) else 0
    earlier = _GUARDED.pop(socket_path, None)
    if earlier is not None and earlier["own"]:
        _finish(socket_path, earlier)      # a relaunch on the same socket loses nothing
    _record(socket_path, proof_defaults.bundle_domain(binary) or proof_defaults.APP_DOMAIN)
    with open(log_path, "ab") as out:
        child = subprocess.Popen(
            [str(binary), "-ApplePersistenceIgnoreState", "YES", *arguments],
            stdin=subprocess.DEVNULL, stdout=out, stderr=subprocess.STDOUT,
            start_new_session=True, env=environment)
    _own(socket_path, child.pid)
    client = None
    if wait_listening(log_path, socket_path, child=child, seconds=seconds, offset=offset):
        try:
            client = MCP(socket_path, timeout=timeout)
        except proof_app.StaleApp:
            Launched(child, socket_path, log_path, None).stop()
            raise
    return Launched(child, socket_path, log_path, client)

import Foundation

/// The agent server's Unix socket (road map 14's MC2, spec §11 MC-1, MC-2,
/// MC-6): where it is bound, whether this instance may bind it, the bind,
/// its release at quit, and the line Settings' MCP section copies. The
/// core's listener (`ReelAgentSocket`) is the app's only one since MC4; it
/// serves the prepared catalog through the trampoline, so every call goes
/// through `AgentLane.serve`'s one lock (AI-2).
///
/// **Bound at every launch, and never an alert.** No person asked for it,
/// so a launch that cannot bind logs one line, `Frame Job agent socket not
/// bound: <reason>`, and carries on; a bound one logs `Frame Job agent socket
/// listening at <path>`. Neither line carries the `Frame Job: ` prefix, which
/// is the parity check's alone.
///
/// **The path** (`socketPlan`) is `RC_AGENT_SOCKET` when it is set and not
/// empty, else `AppSupport`'s folder plus `Agent/agent.sock`. MC-6 says no
/// proof binds the person's socket, so every proof sets `RC_AGENT_SOCKET`.
///
/// **MC-2's policy** (`socketRefusal`), in order: the folder is made by
/// `AppSupport.ensureDirectory` (`0700` at each level it makes) and must
/// then be a real folder — not a symlink — owned by this user with no group
/// or world bits, because its mode is the socket's whole access control and
/// a wrong one is reported, not worked around. A file at the path is asked
/// first: a socket that ACCEPTS a connection belongs to another instance and
/// is left alone; one that REFUSES is a crash's leftover and is unlinked;
/// anything that is not a socket is left alone too (MC-2 sanctions unlinking
/// only a refused socket). The core then binds without unlinking anything
/// and makes the file `0600`.
///
/// **The quit** (`unbindSocket`) is a release, not a stop: the core unlinks
/// the file only while it is still the one this listener bound (MC1's S7)
/// and abandons the listener without a join, so a call in flight that waits
/// on main cannot hold the quit. `AgentServer.shared` is the context and
/// lives for the process, which the release's contract needs.
extension AgentServer {
    enum SocketPlan: Equatable {
        case bind(path: String)
        case skip(reason: String)
    }

    static let socketEnvironmentKey = "RC_AGENT_SOCKET"

    /// The bundle's short version, or "0.0" — what the listener reports as
    /// `serverInfo.version`.
    static var serverVersion: String {
        Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "0.0"
    }

    /// `~/Library/Application Support/Frame Job/Agent/agent.sock` — the path
    /// only; creates nothing.
    static var defaultSocketPath: String? {
        AppSupport.subdirectory("Agent")?.appendingPathComponent("agent.sock").path
    }

    /// Where this launch binds, or why it binds nothing. Pure.
    static func socketPlan(environment: [String: String], defaultPath: String?) -> SocketPlan {
        if let path = environment[socketEnvironmentKey], !path.isEmpty {
            return .bind(path: path)
        }
        guard let defaultPath else { return .skip(reason: "no Application Support folder") }
        return .bind(path: defaultPath)
    }

    /// Binds the socket under MC-2's rules, or logs why not. Main only,
    /// from `applicationDidFinishLaunching`; never throws, never alerts.
    func bindSocket() {
        assert(Thread.isMainThread)
        let plan = Self.socketPlan(
            environment: ProcessInfo.processInfo.environment, defaultPath: Self.defaultSocketPath)
        let path: String
        switch plan {
        case .skip(let reason):
            Self.logSocketNotBound(reason)
            return
        case .bind(let planned):
            path = planned
        }
        if let reason = Self.socketRefusal(at: path) {
            Self.logSocketNotBound(reason)
            return
        }
        do {
            let catalog = try prepareCatalog()
            try ReelAgentSocket.start(
                path: path, serverName: "framejob", version: Self.serverVersion,
                toolsJSON: catalog, handler: agentToolTrampoline,
                context: Unmanaged.passUnretained(self).toOpaque())
        } catch {
            Self.logSocketNotBound(error.localizedDescription)
            return
        }
        boundSocketPath = path
        NSLog("Frame Job agent socket listening at %@", path)
    }

    /// The bundled stdio helper (road map 14's MC3), inside this app's own
    /// bundle wherever it was launched from.
    static var mcpHelperURL: URL {
        Bundle.main.bundleURL.appendingPathComponent("Contents/Helpers/framejob-mcp")
    }

    /// The line Settings' MCP section copies: Claude Code's `mcp add`
    /// for the helper at `helperPath`, single-quoted for a POSIX shell.
    static func mcpCommand(helperPath: String) -> String {
        let quoted = helperPath.replacingOccurrences(of: "'", with: "'\\''")
        return "claude mcp add --scope user framejob -- '\(quoted)'"
    }

    /// For `applicationWillTerminate`: unlinks the socket only if it is
    /// still this instance's, with no join. Safe when none is bound.
    func unbindSocket() {
        ReelAgentSocket.release()
    }

    private static func logSocketNotBound(_ reason: String) {
        NSLog("Frame Job agent socket not bound: %@", reason)
    }

    /// MC-2 before the bind: the folder made and checked, then whatever is
    /// at the path asked and, only when it is a refusing socket, unlinked.
    /// Nil means bind; otherwise the reason nothing is bound.
    static func socketRefusal(at path: String) -> String? {
        let socketURL = URL(fileURLWithPath: path)
        let folder = socketURL.deletingLastPathComponent().path
        do {
            try AppSupport.ensureDirectory(URL(fileURLWithPath: folder, isDirectory: true))
        } catch {
            return "could not make the folder \(folder): \(error.localizedDescription)"
        }

        var folderInfo = stat()
        guard lstat(folder, &folderInfo) == 0 else {
            return "could not read the folder \(folder): \(errnoSentence(errno))"
        }
        guard folderInfo.st_mode & S_IFMT == S_IFDIR else {
            return "\(folder) is not a folder (a symlink is refused)"
        }
        guard folderInfo.st_uid == getuid() else {
            return "\(folder) is owned by uid \(folderInfo.st_uid), not this user (\(getuid()))"

